'use client'
import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes } from 'react'
import styles from './prompt-suggestions.module.css'

export interface PromptSuggestionsProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onSelect'> {
  items: string[]
  onSelect: (value: string) => void
  labels?: {
    group?: string
  }
}

export function PromptSuggestions({
  items,
  onSelect,
  labels,
  className,
  ...props
}: PromptSuggestionsProps) {
  return (
    <div
      role="group"
      aria-label={labels?.group ?? t(builtin.promptSuggestions.group)}
      className={cn(styles['suggestions'], className as string | undefined)}
      {...props}
    >
      {items.map((item) => (
        <button key={item} type="button" className={styles['chip']} onClick={() => onSelect(item)}>
          {item}
        </button>
      ))}
    </div>
  )
}

@layer cascivo.component {
  .suggestions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--cascivo-space-2);
  }

  .chip {
    display: inline-flex;
    align-items: center;
    max-inline-size: 100%;
    padding-block: var(--cascivo-space-2);
    padding-inline: var(--cascivo-space-3);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-surface);
    color: var(--cascivo-color-text);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-snug);
    text-align: start;
    cursor: pointer;
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      border-color: var(--cascivo-color-ai-border);
      background-color: var(--cascivo-color-ai-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    @media (pointer: coarse) {
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }
}

@media (forced-colors: active) {
  .chip {
    border-color: ButtonText;
  }

  .chip:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'PromptSuggestions',
  description:
    'Starter prompts as a wrap of pill buttons — the "Try asking…" row of an empty AI chat',
  category: 'inputs',
  clientJs: 'required',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'items',
      description: 'The prompts, as the exact text each one sends.',
      type: 'string[]',
      required: true,
    },
    {
      name: 'onSelect',
      description: 'Called with the chosen prompt — send it, or put it in the composer.',
      type: '(value: string) => void',
      required: true,
    },
    {
      name: 'labels',
      description:
        'Overrides for the component’s user-visible strings (i18n) — `group` names the group for screen readers.',
      type: '{ group?: string }',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-border',
    '--cascivo-color-surface',
    '--cascivo-color-ai-border',
    '--cascivo-color-ai-subtle',
    '--cascivo-radius-full',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter', 'Space'],
    forcedColors: true,
  },
  examples: [
    {
      title: 'Starter prompts',
      code: `<PromptSuggestions
  items={['Summarise this week’s tickets', 'Draft a release note', 'What changed in v2?']}
  onSelect={() => {}}
/>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['ai', 'chat', 'prompts', 'suggestions', 'starters', 'chips'],
  intent: {
    whenToUse: [
      'An empty conversation: offer a few concrete things to ask',
      'Follow-up suggestions under an assistant reply',
    ],
    whenNotToUse: [
      'Filtering or selecting values — use ToggleGroup, Tag or SegmentedControl',
      'Autocomplete while typing — use Combobox',
    ],
    antiPatterns: [
      {
        bad: 'Ten generic prompts ("Ask me anything")',
        good: 'Three or four specific, tappable prompts',
        why: 'Specific starters show what the assistant can actually do; a long generic list is skipped',
      },
    ],
    related: [
      {
        name: 'MessageActions',
        relationship: 'pairs-with',
        reason: 'Both sit around an assistant message',
      },
      {
        name: 'Tag',
        relationship: 'alternative',
        reason: 'Tag is for labels and filters, not for sending a prompt',
      },
    ],
    a11yRationale:
      'A named group of real buttons whose names are the prompt text, operable with Tab and Enter/Space. Pills meet the coarse-pointer target size and keep a visible focus ring',
    content: {
      tone: 'Write each prompt as the person would type it, in the first person',
    },
    flexibility: [
      {
        area: 'what selecting does',
        level: 'flexible',
        note: 'Send immediately, or fill the composer',
      },
      {
        area: 'item text',
        level: 'strict',
        note: 'The visible text is the prompt; do not show one thing and send another',
      },
    ],
  },
}
